(()=>{'use strict';const D=window.BK_DATA,W=window.BK_STATUTES;if(!D?.crimes||!W)return;
const rows=[{"id":"narkotikabrott-innehav","title":"Narkotikabrott · innehav","shortRef":"NSL 1 §","family":"NSL","rule":"NSL","previousMode":"general","ownText":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"ringa-narkotikabrott-bruk","title":"Ringa narkotikabrott · bruk","shortRef":"NSL 2 §","family":"NSL","rule":"NSL","previousMode":"general","ownText":"2 § Är brott som avses i 1 § första stycket med hänsyn till arten och mängden narkotika samt övriga omständigheter att anse som ringa, döms för ringa narkotikabrott till böter eller fängelse i högst sex månader. Lag (2016:488).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"narkotikabrott-overlatelse","title":"Narkotikabrott · överlåtelse","shortRef":"NSL 1 § 1 st. 1","family":"NSL","rule":"NSL","previousMode":"general","ownText":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"narkotikabrott-framstallning","title":"Narkotikabrott · framställning","shortRef":"NSL 1 § 1 st. 2","family":"NSL","rule":"NSL","previousMode":"general","ownText":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"narkotikabrott-forvarv","title":"Narkotikabrott · förvärv i överlåtelsesyfte","shortRef":"NSL 1 § 1 st. 3","family":"NSL","rule":"NSL","previousMode":"general","ownText":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"narkotikabrott-transport","title":"Narkotikabrott · transport/förvaring","shortRef":"NSL 1 § 1 st. 4","family":"NSL","rule":"NSL","previousMode":"general","ownText":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"narkotikabrott-forsaljning","title":"Narkotikabrott · försäljning","shortRef":"NSL 1 § 2 st.","family":"NSL","rule":"NSL","previousMode":"general","ownText":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"narkotikabrott-framja","title":"Narkotikabrott · främjande av handel","shortRef":"NSL 1 § 3 st.","family":"NSL","rule":"NSL","previousMode":"general","ownText":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"ringa-narkotikabrott-innehav","title":"Ringa narkotikabrott · innehav","shortRef":"NSL 2 § jfr 1 §","family":"NSL","rule":"NSL","previousMode":"general","ownText":"2 § Är brott som avses i 1 § första stycket med hänsyn till arten och mängden narkotika samt övriga omständigheter att anse som ringa, döms för ringa narkotikabrott till böter eller fängelse i högst sex månader. Lag (2016:488).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"grovt-narkotikabrott","title":"Grovt narkotikabrott","shortRef":"NSL 3 §","family":"NSL","rule":"NSL","previousMode":"general","ownText":"3 § Är brott som avses i 1 § att anse som grovt, döms för grovt narkotikabrott till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om brottet har utgjort ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, avsett en särskilt stor mängd narkotika eller annars varit av särskilt farlig eller hänsynslös art. Är brottet att anse som synnerligen grovt, döms för synnerligen grovt narkotikabrott till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om brottet har utgjort ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, avsett en synnerligen stor mängd narkotika eller annars varit av synnerligen farlig eller hänsynslös art. Lag (2023:258).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"synnerligen-grovt-narkotikabrott","title":"Synnerligen grovt narkotikabrott","shortRef":"NSL 3 § 2 st.","family":"NSL","rule":"NSL","previousMode":"general","ownText":"3 § Är brott som avses i 1 § att anse som grovt, döms för grovt narkotikabrott till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om brottet har utgjort ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, avsett en särskilt stor mängd narkotika eller annars varit av särskilt farlig eller hänsynslös art. Är brottet att anse som synnerligen grovt, döms för synnerligen grovt narkotikabrott till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om brottet har utgjort ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, avsett en synnerligen stor mängd narkotika eller annars varit av synnerligen farlig eller hänsynslös art. Lag (2023:258).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"vapenbrott","title":"Vapenbrott","shortRef":"VapenL 18:1","family":"VapenL","rule":"VapenL","previousMode":"general","ownText":"18 kap. 1 § Den som uppsåtligen innehar eller tillverkar ett skjutvapen utan att ha rätt till det eller överlåter, yrkesmässigt förmedlar eller lånar ut ett skjutvapen till någon som inte har rätt att inneha vapnet döms för vapenbrott till fängelse i högst fem år. Om brottet med hänsyn till risken för att vapnet skulle komma till brottslig eller annan skadlig användning och övriga omständigheter är att anse som mindre allvarligt, döms till böter eller fängelse i högst sex månader. Till böter eller fängelse i högst sex månader döms också den som har begått gärningen av oaktsamhet. Lag (2026:1250).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","Vapen:18:14"]},{"id":"vapenbrott-mindre","title":"Mindre allvarligt vapenbrott","shortRef":"VapenL 18:1 st. 2","family":"VapenL","rule":"VapenL","previousMode":"general","ownText":"18 kap. 1 § Den som uppsåtligen innehar eller tillverkar ett skjutvapen utan att ha rätt till det eller överlåter, yrkesmässigt förmedlar eller lånar ut ett skjutvapen till någon som inte har rätt att inneha vapnet döms för vapenbrott till fängelse i högst fem år. Om brottet med hänsyn till risken för att vapnet skulle komma till brottslig eller annan skadlig användning och övriga omständigheter är att anse som mindre allvarligt, döms till böter eller fängelse i högst sex månader. Till böter eller fängelse i högst sex månader döms också den som har begått gärningen av oaktsamhet. Lag (2026:1250).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","Vapen:18:14"]},{"id":"vapenbrott-oaktsamt","title":"Vapenbrott av oaktsamhet","shortRef":"VapenL 18:1 st. 3","family":"VapenL","rule":"VapenL","previousMode":"general","ownText":"18 kap. 1 § Den som uppsåtligen innehar eller tillverkar ett skjutvapen utan att ha rätt till det eller överlåter, yrkesmässigt förmedlar eller lånar ut ett skjutvapen till någon som inte har rätt att inneha vapnet döms för vapenbrott till fängelse i högst fem år. Om brottet med hänsyn till risken för att vapnet skulle komma till brottslig eller annan skadlig användning och övriga omständigheter är att anse som mindre allvarligt, döms till böter eller fängelse i högst sex månader. Till böter eller fängelse i högst sex månader döms också den som har begått gärningen av oaktsamhet. Lag (2026:1250).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","Vapen:18:14"]},{"id":"grovt-vapenbrott","title":"Grovt vapenbrott","shortRef":"VapenL 18:2","family":"VapenL","rule":"VapenL","previousMode":"general","ownText":"18 kap. 2 § Om ett brott som avses i 1 § första stycket är grovt, döms för grovt vapenbrott till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. vapnet har innehafts på allmän plats eller på en annan plats där människor brukar samlas eller har samlats eller i ett fordon på en sådan plats, 2. vapnet har varit av särskilt farlig beskaffenhet, 3. innehavet, tillverkningen, överlåtelsen, förmedlingen eller utlåningen har avsett flera vapen, 4. vapnet har innehafts eller tillverkats i en sådan miljö att det typiskt sett kan befaras komma till brottslig användning, eller 5. gärningen annars har varit av särskilt farlig art. Om ett brott som avses i 1 § första stycket är synnerligen grovt, döms för synnerligen grovt vapenbrott till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om innehavet, tillverkningen, överlåtelsen, förmedlingen eller utlåningen har avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt första och andra styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2026:1250).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","Vapen:18:14"]},{"id":"synnerligen-grovt-vapenbrott","title":"Synnerligen grovt vapenbrott","shortRef":"VapenL 18:2 st. 2","family":"VapenL","rule":"VapenL","previousMode":"general","ownText":"18 kap. 2 § Om ett brott som avses i 1 § första stycket är grovt, döms för grovt vapenbrott till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. vapnet har innehafts på allmän plats eller på en annan plats där människor brukar samlas eller har samlats eller i ett fordon på en sådan plats, 2. vapnet har varit av särskilt farlig beskaffenhet, 3. innehavet, tillverkningen, överlåtelsen, förmedlingen eller utlåningen har avsett flera vapen, 4. vapnet har innehafts eller tillverkats i en sådan miljö att det typiskt sett kan befaras komma till brottslig användning, eller 5. gärningen annars har varit av särskilt farlig art. Om ett brott som avses i 1 § första stycket är synnerligen grovt, döms för synnerligen grovt vapenbrott till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om innehavet, tillverkningen, överlåtelsen, förmedlingen eller utlåningen har avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt första och andra styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2026:1250).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","Vapen:18:14"]},{"id":"rattfylleri","title":"Rattfylleri","shortRef":"TBL 4 §","family":"TBL","rule":"TBL","previousMode":"general","ownText":"4 § Den som för ett motordrivet fordon eller en spårvagn efter att ha intagit alkohol i så stor mängd att alkoholkoncentrationen under eller efter färden uppgår till minst 0,2 promille i blodet eller 0,10 milligram per liter i utandningsluften döms för rattfylleri till böter eller fängelse i högst sex månader. För rattfylleri enligt första stycket döms också den som för ett motordrivet fordon eller en spårvagn efter att ha intagit narkotika som avses i 8 § narkotikastrafflagen (1968:64) i så stor mängd att det under eller efter färden finns något narkotiskt ämne kvar i blodet. Detta gäller dock inte om narkotikan intagits i enlighet med läkares eller annan behörig receptutfärdares ordination. För rattfylleri enligt första stycket döms också den som för ett motordrivet fordon eller en spårvagn och då är så påverkad av alkohol att det kan antas att han eller hon inte kan framföra fordonet på ett betryggande sätt. Detsamma gäller om föraren är lika påverkad av något annat medel. Första och andra styckena gäller inte förare av ett motordrivet fordon, som är avsett att föras av gående. Första, andra och tredje styckena gäller inte om förandet av fordonet ingår som ett led i en vetenskaplig eller därmed jämförlig undersökning till vilken tillstånd har lämnats av regeringen eller den myndighet som regeringen bestämmer. Lag (2019:346).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"grovt-rattfylleri","title":"Grovt rattfylleri","shortRef":"TBL 4 a §","family":"TBL","rule":"TBL","previousMode":"general","ownText":"4 a § Är ett brott som avses i 4 § första, andra eller tredje stycket att anse som grovt, skall föraren dömas för grovt rattfylleri till fängelse i högst två år. Vid bedömande av om brottet är grovt skall särskilt beaktas om 1. föraren har haft en alkoholkoncentration som uppgått till minst 1,0 promille i blodet eller 0,50 milligram per liter i utandningsluften, 2. föraren annars har varit avsevärt påverkad av alkohol eller något annat medel, eller 3. framförandet av fordonet har inneburit en påtaglig fara för trafiksäkerheten. Lag (1999:217).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"olovlig-korning","title":"Olovlig körning","shortRef":"TBL 3 §","family":"TBL","rule":"TBL","previousMode":"general","ownText":"3 § För någon uppsåtligen körkortspliktigt fordon utan att vara berättigad att föra sådant fordon, dömes för olovlig körning till böter. Har han tidigare innehaft körkort som blivit återkallat eller har brottet skett vanemässigt eller är det eljest att anse som grovt, må dömas till fängelse i högst sex månader. För någon körkortspliktigt fordon med uppsåtligt eller oaktsamt åsidosättande av föreskrift, som meddelats i fråga om rätten att föra sådant fordon, dömes till böter. Om någon uppsåtligen eller av oaktsamhet såsom förare av körkortspliktigt fordon anställer och brukar den som inte äger rätt att föra fordonet, eller i annat fall tillåter någon annan att föra sådant fordon utan att denne är berättigad därtill, dömes likaledes till böter. Första-tredje styckena äger motsvarande tillämpning på förare av traktor, moped klass II, snöskoter, terränghjuling, motorredskap eller spårvagn och på den som anställer eller brukar sådan förare eller eljest tillåter någon att föra sådant fordon. Lag (2009:122).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"grov-olovlig-korning","title":"Grov olovlig körning","shortRef":"TBL 3 §","family":"TBL","rule":"TBL","previousMode":"general","ownText":"3 § För någon uppsåtligen körkortspliktigt fordon utan att vara berättigad att föra sådant fordon, dömes för olovlig körning till böter. Har han tidigare innehaft körkort som blivit återkallat eller har brottet skett vanemässigt eller är det eljest att anse som grovt, må dömas till fängelse i högst sex månader. För någon körkortspliktigt fordon med uppsåtligt eller oaktsamt åsidosättande av föreskrift, som meddelats i fråga om rätten att föra sådant fordon, dömes till böter. Om någon uppsåtligen eller av oaktsamhet såsom förare av körkortspliktigt fordon anställer och brukar den som inte äger rätt att föra fordonet, eller i annat fall tillåter någon annan att föra sådant fordon utan att denne är berättigad därtill, dömes likaledes till böter. Första-tredje styckena äger motsvarande tillämpning på förare av traktor, moped klass II, snöskoter, terränghjuling, motorredskap eller spårvagn och på den som anställer eller brukar sådan förare eller eljest tillåter någon att föra sådant fordon. Lag (2009:122).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"knivbrott","title":"Brott mot knivlagen","shortRef":"KnivL 4 § jfr 1 §","family":"KnivL","rule":"KnivL","previousMode":"general","ownText":"4 § Den som uppsåtligen bryter mot 1 eller 2 § döms till böter eller fängelse i högst ett år. Om gärningen har begåtts av oaktsamhet, döms till böter eller fängelse i högst sex månader. Om ett brott som avses i första stycket är grovt, döms till fängelse i lägst sex månader och högst två år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. föremålet har innehafts i ett sammanhang där det kan befaras komma till användning vid brottsligt angrepp på någons liv, hälsa eller trygghet till person, 2. föremålet har varit av särskilt farlig beskaffenhet, 3. innehavet, överlåtelsen eller saluhållandet har avsett flera föremål, eller 4. gärningen på annat sätt har varit av särskilt farlig art. Om det rör sig om ringa fall utgör gärningen dock inte brott. Lag (2022:608).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"grovt-knivbrott","title":"Grovt brott mot knivlagen","shortRef":"KnivL 4 § st. 3","family":"KnivL","rule":"KnivL","previousMode":"general","ownText":"4 § Den som uppsåtligen bryter mot 1 eller 2 § döms till böter eller fängelse i högst ett år. Om gärningen har begåtts av oaktsamhet, döms till böter eller fängelse i högst sex månader. Om ett brott som avses i första stycket är grovt, döms till fängelse i lägst sex månader och högst två år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. föremålet har innehafts i ett sammanhang där det kan befaras komma till användning vid brottsligt angrepp på någons liv, hälsa eller trygghet till person, 2. föremålet har varit av särskilt farlig beskaffenhet, 3. innehavet, överlåtelsen eller saluhållandet har avsett flera föremål, eller 4. gärningen på annat sätt har varit av särskilt farlig art. Om det rör sig om ringa fall utgör gärningen dock inte brott. Lag (2022:608).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"v09-smuggling","title":"Smuggling","shortRef":"SmuglL 3","family":"SmuglL","rule":"smuggleFee","previousMode":"conditional","ownText":"3 § Den som, i samband med införsel till landet av en vara som omfattas av ett särskilt föreskrivet förbud mot eller villkor för införsel, uppsåtligen bryter mot förbudet eller villkoret genom att underlåta att anmäla varan till tullbehandling, döms för smuggling till böter eller fängelse i högst två år. Det som föreskrivs i första stycket gäller också den som, i samband med att en sådan vara förs in till landet, uppsåtligen lämnar oriktig uppgift vid tullbehandling eller underlåter att lämna föreskriven uppgift vid tullbehandling och därigenom ger upphov till fara för att införseln fullföljs i strid med förbudet eller villkoret. För smuggling döms också den som uppsåtligen 1. från landet för ut en vara i strid med ett särskilt föreskrivet förbud mot eller villkor för utförsel eller efter utförseln förfogar över varan i strid med förbudet eller villkoret, 2. under pågående tullbehandling förfogar över en vara som omfattas av ett särskilt föreskrivet förbud mot eller villkor för införsel och därigenom föranleder att införseln fullföljs i strid med förbudet eller villkoret, 3. till landet för in eller från landet för ut en vara med stöd av ett tillstånd som föranletts av att någon lämnat oriktig uppgift eller underlåtit att lämna föreskriven uppgift till en tillståndsmyndighet eller förfar på ett sådant sätt hos en tillståndsmyndighet och därigenom föranleder att tillstånd meddelas och att varan förs in till eller ut från landet med stöd av tillståndet, eller 4. förfogar över en vara i strid med villkor som uppställts för eller i samband med varans införsel eller utförsel. I det fall bestämmelserna om tullbehandling inte är tillämpliga vid införsel från eller utförsel till ett annat EU-land, gäller det som anges i första och andra styckena om tullbehandling i stället för förfaranden enligt inregränslagen (1996:701). Lag (2024:739) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-ringa-smuggling","title":"Ringa smuggling","shortRef":"SmuglL 4","family":"SmuglL","rule":"smuggleFee","previousMode":"conditional","ownText":"4 § Om ett brott som avses i 3 § är att anse som ringa, döms till penningböter.","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-grov-smuggling","title":"Grov smuggling","shortRef":"SmuglL 5","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"5 § Om ett brott som avses i 3 § är att anse som grovt, döms för grov smuggling till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen ingått som ett led i en brottslighet som utövats systematiskt eller i större omfattning, om gärningen med hänsyn till omständigheterna kring införseln, utförseln eller förfogandet varit av särskilt farlig art eller om gärningen annars inneburit en allvarlig kränkning av ett betydande samhällsintresse. Lag (2026:1321) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-narkotikasmuggling","title":"Narkotikasmuggling","shortRef":"SmuglL 6","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 § Om en gärning som avses i 3 § gäller narkotika, döms för narkotikasmuggling till fängelse i högst tre år. Om narkotikan är avsedd att säljas, döms till fängelse i lägst sex månader och högst tre år. Om brott som avses i första stycket är ringa, döms för ringa narkotikasmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov narkotikasmuggling till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett en särskilt stor mängd narkotika, om gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller om verksamheten eller gärningen annars varit av särskilt farlig eller hänsynslös art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov narkotikasmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen har ingått som ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, om gärningen avsett en synnerligen stor mängd narkotika, eller om verksamheten eller gärningen annars varit av synnerligen farlig eller hänsynslös art. Lag (2025:645) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-narkotikasmuggling-avsedd-att-saljas","title":"Narkotikasmuggling – avsedd att säljas","shortRef":"SmuglL 6","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 § Om en gärning som avses i 3 § gäller narkotika, döms för narkotikasmuggling till fängelse i högst tre år. Om narkotikan är avsedd att säljas, döms till fängelse i lägst sex månader och högst tre år. Om brott som avses i första stycket är ringa, döms för ringa narkotikasmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov narkotikasmuggling till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett en särskilt stor mängd narkotika, om gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller om verksamheten eller gärningen annars varit av särskilt farlig eller hänsynslös art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov narkotikasmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen har ingått som ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, om gärningen avsett en synnerligen stor mängd narkotika, eller om verksamheten eller gärningen annars varit av synnerligen farlig eller hänsynslös art. Lag (2025:645) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-ringa-narkotikasmuggling","title":"Ringa narkotikasmuggling","shortRef":"SmuglL 6","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 § Om en gärning som avses i 3 § gäller narkotika, döms för narkotikasmuggling till fängelse i högst tre år. Om narkotikan är avsedd att säljas, döms till fängelse i lägst sex månader och högst tre år. Om brott som avses i första stycket är ringa, döms för ringa narkotikasmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov narkotikasmuggling till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett en särskilt stor mängd narkotika, om gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller om verksamheten eller gärningen annars varit av särskilt farlig eller hänsynslös art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov narkotikasmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen har ingått som ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, om gärningen avsett en synnerligen stor mängd narkotika, eller om verksamheten eller gärningen annars varit av synnerligen farlig eller hänsynslös art. Lag (2025:645) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-grov-narkotikasmuggling","title":"Grov narkotikasmuggling","shortRef":"SmuglL 6","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 § Om en gärning som avses i 3 § gäller narkotika, döms för narkotikasmuggling till fängelse i högst tre år. Om narkotikan är avsedd att säljas, döms till fängelse i lägst sex månader och högst tre år. Om brott som avses i första stycket är ringa, döms för ringa narkotikasmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov narkotikasmuggling till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett en särskilt stor mängd narkotika, om gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller om verksamheten eller gärningen annars varit av särskilt farlig eller hänsynslös art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov narkotikasmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen har ingått som ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, om gärningen avsett en synnerligen stor mängd narkotika, eller om verksamheten eller gärningen annars varit av synnerligen farlig eller hänsynslös art. Lag (2025:645) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-synnerligen-grov-narkotikasmuggling","title":"Synnerligen grov narkotikasmuggling","shortRef":"SmuglL 6","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 § Om en gärning som avses i 3 § gäller narkotika, döms för narkotikasmuggling till fängelse i högst tre år. Om narkotikan är avsedd att säljas, döms till fängelse i lägst sex månader och högst tre år. Om brott som avses i första stycket är ringa, döms för ringa narkotikasmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov narkotikasmuggling till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett en särskilt stor mängd narkotika, om gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller om verksamheten eller gärningen annars varit av särskilt farlig eller hänsynslös art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov narkotikasmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen har ingått som ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, om gärningen avsett en synnerligen stor mängd narkotika, eller om verksamheten eller gärningen annars varit av synnerligen farlig eller hänsynslös art. Lag (2025:645) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-vapensmuggling","title":"Vapensmuggling","shortRef":"SmuglL 6 a","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 a § Om en gärning som avses i 3 § gäller vapen, döms för vapensmuggling till fängelse i högst fem år. Om brottet är ringa, döms för ringa vapensmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov vapensmuggling till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett ett vapen av särskilt farlig beskaffenhet, 2. gärningen avsett flera vapen, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov vapensmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt tredje och fjärde styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2023:873) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-ringa-vapensmuggling","title":"Ringa vapensmuggling","shortRef":"SmuglL 6 a","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 a § Om en gärning som avses i 3 § gäller vapen, döms för vapensmuggling till fängelse i högst fem år. Om brottet är ringa, döms för ringa vapensmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov vapensmuggling till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett ett vapen av särskilt farlig beskaffenhet, 2. gärningen avsett flera vapen, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov vapensmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt tredje och fjärde styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2023:873) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-grov-vapensmuggling","title":"Grov vapensmuggling","shortRef":"SmuglL 6 a","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 a § Om en gärning som avses i 3 § gäller vapen, döms för vapensmuggling till fängelse i högst fem år. Om brottet är ringa, döms för ringa vapensmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov vapensmuggling till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett ett vapen av särskilt farlig beskaffenhet, 2. gärningen avsett flera vapen, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov vapensmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt tredje och fjärde styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2023:873) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-synnerligen-grov-vapensmuggling","title":"Synnerligen grov vapensmuggling","shortRef":"SmuglL 6 a","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 a § Om en gärning som avses i 3 § gäller vapen, döms för vapensmuggling till fängelse i högst fem år. Om brottet är ringa, döms för ringa vapensmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov vapensmuggling till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett ett vapen av särskilt farlig beskaffenhet, 2. gärningen avsett flera vapen, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov vapensmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt tredje och fjärde styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2023:873) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-smuggling-av-explosiv-vara","title":"Smuggling av explosiv vara","shortRef":"SmuglL 6 b","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 b § Om en gärning som avses i 3 § gäller explosiva varor, döms för smuggling av explosiv vara till böter eller fängelse i högst fem år. Om brottet är ringa, döms för ringa smuggling av explosiv vara till penningböter. Om brottet är att anse som grovt, döms för grov smuggling av explosiv vara till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett en vara som med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. gärningen avsett flera varor eller en stor mängd av en vara, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov smuggling av explosiv vara till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:873) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-ringa-smuggling-av-explosiv-vara","title":"Ringa smuggling av explosiv vara","shortRef":"SmuglL 6 b","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 b § Om en gärning som avses i 3 § gäller explosiva varor, döms för smuggling av explosiv vara till böter eller fängelse i högst fem år. Om brottet är ringa, döms för ringa smuggling av explosiv vara till penningböter. Om brottet är att anse som grovt, döms för grov smuggling av explosiv vara till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett en vara som med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. gärningen avsett flera varor eller en stor mängd av en vara, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov smuggling av explosiv vara till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:873) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-grov-smuggling-av-explosiv-vara","title":"Grov smuggling av explosiv vara","shortRef":"SmuglL 6 b","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 b § Om en gärning som avses i 3 § gäller explosiva varor, döms för smuggling av explosiv vara till böter eller fängelse i högst fem år. Om brottet är ringa, döms för ringa smuggling av explosiv vara till penningböter. Om brottet är att anse som grovt, döms för grov smuggling av explosiv vara till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett en vara som med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. gärningen avsett flera varor eller en stor mängd av en vara, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov smuggling av explosiv vara till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:873) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-synnerligen-grov-smuggling-av-explosiv-vara","title":"Synnerligen grov smuggling av explosiv vara","shortRef":"SmuglL 6 b","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"6 b § Om en gärning som avses i 3 § gäller explosiva varor, döms för smuggling av explosiv vara till böter eller fängelse i högst fem år. Om brottet är ringa, döms för ringa smuggling av explosiv vara till penningböter. Om brottet är att anse som grovt, döms för grov smuggling av explosiv vara till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett en vara som med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. gärningen avsett flera varor eller en stor mängd av en vara, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov smuggling av explosiv vara till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:873) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-olovlig-inforsel-eller-utforsel","title":"Olovlig införsel eller utförsel","shortRef":"SmuglL 7","family":"SmuglL","rule":"smuggleFee","previousMode":"conditional","ownText":"7 § Den som av grov oaktsamhet begår en gärning som avses i 3, 6, 6 a eller 6 b §, döms för olovlig införsel eller olovlig utförsel till böter eller fängelse i högst två år. För olovlig införsel eller olovlig utförsel döms också den som av grov oaktsamhet 1. i samband med utförsel från landet av en vara underlåter att anmäla varan till tullbehandling, lämnar oriktig uppgift vid tullbehandling eller underlåter att lämna föreskriven uppgift vid tullbehandling och därigenom ger upphov till fara för att sådant förbud eller villkor som avses i 3 § tredje stycket 1 eller den bestämmelsen tillsammans med 6, 6 a eller 6 b § överträds, eller 2. lämnar oriktig uppgift eller underlåter att lämna föreskriven uppgift i samband med ansökan om sådant tillstånd som avses i 3 § tredje stycket 3 eller den bestämmelsen tillsammans med 6, 6 a eller 6 b § och därigenom ger upphov till fara för att varan förs in eller ut med stöd av detta tillstånd. I de fall bestämmelserna om tullbehandling inte är tillämpliga vid utförsel till ett annat EU-land, gäller vad som anges i andra stycket 1 om tullbehandling i stället för förfaranden enligt inregränslagen (1996:701). Om gärningen är ringa, ska den inte medföra ansvar. Lag (2024:739) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-tullbrott","title":"Tullbrott","shortRef":"SmuglL 8","family":"SmuglL","rule":"smuggleSurcharge","previousMode":"conditional","ownText":"8 § Den som, i samband med att en vara förs in till landet, uppsåtligen underlåter att anmäla varan till tullbehandling, lämnar oriktig uppgift vid tullbehandling eller underlåter att lämna föreskriven uppgift vid tullbehandling och därigenom ger upphov till fara för att tull, annan skatt eller avgift undandras det allmänna, döms för tullbrott till böter eller fängelse i högst två år. För tullbrott döms också den som uppsåtligen ger upphov till fara för att tull, annan skatt eller avgift undandras det allmänna eller felaktigt tillgodoräknas eller återbetalas till honom själv eller annan genom att 1. i samband med att en vara förs ut från landet, förfara så som anges i första stycket eller, efter utförseln, förfoga över varan i strid med vad som förutsatts vid den tullbehandling som skett med anledning av utförseln, 2. under pågående tullbehandling förfoga över en införd vara i strid med vad som gäller för denna tullbehandling, eller 3. bryta mot villkor som vid tullbehandling för övergång till fri omsättning har uppställts för befrielse från eller nedsättning av skatten eller avgiften. Om en tulldeklaration ges in i ett annat EU-land med stöd av ett tillstånd för centraliserad klarering enligt artikel 179 i Europaparlamentets och rådets förordning (EU) nr 952/2013 av den 9 oktober 2013 om fastställande av en tullkodex för unionen, gäller första stycket sådana uppgifter som avses i 2 kap. 2 a § andra stycket tullagen (2016:253). Denna bestämmelse är tillämplig endast i fråga om sådana tullar, andra skatter och avgifter som Tullverket ska besluta. Lag (2021:1152) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-ringa-tullbrott","title":"Ringa tullbrott","shortRef":"SmuglL 9","family":"SmuglL","rule":"smuggleSurcharge","previousMode":"conditional","ownText":"9 § Om ett brott som avses i 8 § är att anse som ringa, döms till penningböter.","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-grovt-tullbrott","title":"Grovt tullbrott","shortRef":"SmuglL 10","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"10 § Om ett brott som avses i 8 § är att anse som grovt, döms för grovt tullbrott till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen rört mycket betydande belopp, om gärningsmannen använt falska handlingar eller vilseledande bokföring, om gärningen ingått som ett led i en brottslighet som utövats systematiskt eller i större omfattning eller om gärningen annars varit av särskilt farlig art. Lag (2026:1321) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-vardslos-tullredovisning","title":"Vårdslös tullredovisning","shortRef":"SmuglL 11","family":"SmuglL","rule":"smuggleSurcharge","previousMode":"conditional","ownText":"11 § Den som av grov oaktsamhet begår gärning som avses i 8 §, döms för vårdslös tullredovisning till böter eller fängelse i högst två år. Om gärningen är ringa, skall den inte medföra ansvar.","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-olovlig-befattning-med-smuggelgods","title":"Olovlig befattning med smuggelgods","shortRef":"SmuglL 12","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"12 § Den som uppsåtligen emballerar, transporterar, förvarar, döljer, bearbetar, förvärvar, överlåter eller ingår avtal om upplåtelse av panträtt i en vara som varit föremål för brott enligt 3-11 §§, döms för olovlig befattning med smuggelgods till böter eller fängelse i högst två år. Gärningen ska inte medföra ansvar, om den är ringa med hänsyn till befattningen, omständigheterna kring denna, egendomens beskaffenhet och värde samt övriga omständigheter. Om gärningsmannen inte inser men har skälig anledning att anta att varan varit föremål för brott, döms till böter. Om gärningen är ringa, ska den inte medföra ansvar. Ansvar enligt första eller andra stycket ska inte dömas ut, om gärningen är belagd med straff i - 1 § första stycket 1, 3 eller 4 narkotikastrafflagen (1968:64) eller i 2 eller 3 a § narkotikastrafflagen jämförd med dessa bestämmelser, - 18 kap. 1 eller 2 § vapenlagen (2026:408), eller - 29 § andra stycket 2 eller 29 a § lagen (2010:1011) om brandfarliga och explosiva varor. Lag (2026:417) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-grov-olovlig-befattning-med-smuggelgods","title":"Grov olovlig befattning med smuggelgods","shortRef":"SmuglL 13","family":"SmuglL","rule":"smuggleGeneral","previousMode":"general","ownText":"13 § Om ett brott som avses i 12 § första stycket är att anse som grovt, döms för grov olovlig befattning med smuggelgods till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen ingått som ett led i en brottslighet som utövats systematiskt eller i större omfattning, om gärningen avsett befattning med varor som varit föremål för brott varigenom tull, annan skatt eller avgift till mycket betydande belopp har undandragits det allmänna eller felaktigt återbetalats eller tillgodoräknats någon eller om gärningen annars varit av särskilt farlig art. Lag (2026:1321) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SmuglL:20"]},{"id":"v09-penningtvattsbrott","title":"Penningtvättsbrott","shortRef":"PTBL 3–4","family":"PTBL","rule":"PTBL","previousMode":"general","ownText":"3 § För penningtvättsbrott döms, om åtgärden syftar till att dölja att pengar eller annan egendom härrör från brott eller brottslig verksamhet eller till att främja möjligheterna för någon att tillgodogöra sig egendomen eller dess värde, den som 1. överlåter, förvärvar, omsätter, förvarar eller vidtar annan sådan åtgärd med egendomen, eller 2. tillhandahåller, förvärvar eller upprättar en handling som kan ge en skenbar förklaring till innehavet av egendomen, deltar i transaktioner som utförs för skens skull, uppträder som bulvan eller vidtar annan sådan åtgärd. Straffet är fängelse i högst två år. 4 § För penningtvättsbrott döms även den som, utan att åtgärden har ett sådant syfte som anges i 3 §, otillbörligen främjar möjligheterna för någon att omsätta pengar eller annan egendom som härrör från brott eller brottslig verksamhet.","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"v09-grovt-penningtvattsbrott","title":"Grovt penningtvättsbrott","shortRef":"PTBL 5","family":"PTBL","rule":"PTBL","previousMode":"general","ownText":"5 § Är brott som avses i 3 eller 4 § grovt, döms för grovt penningtvättsbrott till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett betydande värden, om de brottsliga åtgärderna har ingått som ett led i en brottslighet som utövats systematiskt eller i större omfattning eller i annat fall varit av särskilt farlig art. Lag (2026:1323) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"v09-penningtvattsforseelse","title":"Penningtvättsförseelse","shortRef":"PTBL 6","family":"PTBL","rule":"PTBL","previousMode":"general","ownText":"6 § Är brott som avses i 3 eller 4 § ringa, döms för penningtvättsförseelse till böter eller fängelse i högst sex månader. För penningtvättsförseelse döms även den som i fall som avses i 3 eller 4 § inte insåg men hade skälig anledning att anta att egendomen härrörde från brott eller brottslig verksamhet.","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"v09-naringspenningtvatt","title":"Näringspenningtvätt","shortRef":"PTBL 7","family":"PTBL","rule":"PTBL","previousMode":"general","ownText":"7 § Den som, i näringsverksamhet eller såsom led i en verksamhet som bedrivs vanemässigt eller annars i större omfattning, medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §, döms för näringspenningtvätt till fängelse i högst två år. Är brottet grovt, döms till fängelse i lägst ett och högst sex år. Är brottet ringa, döms till böter eller fängelse i högst sex månader. Till samma straff döms den som i annat fall än som anges i första stycket medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §. Lag (2026:1323) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"v09-grov-naringspenningtvatt","title":"Grov näringspenningtvätt","shortRef":"PTBL 7","family":"PTBL","rule":"PTBL","previousMode":"general","ownText":"7 § Den som, i näringsverksamhet eller såsom led i en verksamhet som bedrivs vanemässigt eller annars i större omfattning, medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §, döms för näringspenningtvätt till fängelse i högst två år. Är brottet grovt, döms till fängelse i lägst ett och högst sex år. Är brottet ringa, döms till böter eller fängelse i högst sex månader. Till samma straff döms den som i annat fall än som anges i första stycket medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §. Lag (2026:1323) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"v09-ringa-naringspenningtvatt","title":"Ringa näringspenningtvätt","shortRef":"PTBL 7","family":"PTBL","rule":"PTBL","previousMode":"general","ownText":"7 § Den som, i näringsverksamhet eller såsom led i en verksamhet som bedrivs vanemässigt eller annars i större omfattning, medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §, döms för näringspenningtvätt till fängelse i högst två år. Är brottet grovt, döms till fängelse i lägst ett och högst sex år. Är brottet ringa, döms till böter eller fängelse i högst sex månader. Till samma straff döms den som i annat fall än som anges i första stycket medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §. Lag (2026:1323) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"v09-skattebrott","title":"Skattebrott","shortRef":"SkBrL 2","family":"SkBrL","rule":"taxThreshold","previousMode":"conditional","ownText":"2 § Den som uppsåtligen lämnar oriktig uppgift till en myndighet eller låter bli att till en myndighet lämna deklaration, kontrolluppgift eller annan föreskriven uppgift och därigenom ger upphov till fara för att skatt undandras det allmänna eller felaktigt tillgodoräknas eller återbetalas till personen själv eller annan, döms för skattebrott till fängelse i högst två år. Lag (2026:109).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SkBrL:13","SkBrL:13b"]},{"id":"v09-skatteforseelse","title":"Skatteförseelse","shortRef":"SkBrL 3","family":"SkBrL","rule":"taxMinor","previousMode":"conditional","ownText":"3 § Om brott som avses i 2 § är att anse som ringa, döms för skatteförseelse till böter. Lag (1996:658).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SkBrL:13","SkBrL:13b"]},{"id":"v09-grovt-skattebrott","title":"Grovt skattebrott","shortRef":"SkBrL 4","family":"SkBrL","rule":"taxOther","previousMode":"conditional","ownText":"4 § Om brott som avses i 2 § är att anse som grovt, döms för grovt skattebrott till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om det rört mycket betydande belopp, om gärningsmannen använt falska handlingar eller vilseledande bokföring eller om förfarandet ingått som ett led i en brottslighet som utövats systematiskt eller i större omfattning eller i annat fall varit av synnerligen farlig art. Lag (2026:1320).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SkBrL:13","SkBrL:13b"]},{"id":"v09-vardslos-skatteuppgift","title":"Vårdslös skatteuppgift","shortRef":"SkBrL 5","family":"SkBrL","rule":"taxThreshold","previousMode":"conditional","ownText":"5 § Den som av grov oaktsamhet lämnar oriktig uppgift till en myndighet och därigenom ger upphov till fara för att skatt undandras det allmänna eller felaktigt tillgodoräknas eller återbetalas till uppgiftslämnaren eller annan döms för vårdslös skatteuppgift till böter eller fängelse i högst ett år. Om gärningen med hänsyn till skattebeloppet och övriga omständigheter är av mindre allvarlig art, ska det inte dömas till ansvar enligt första stycket. Lag (2026:109).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SkBrL:13","SkBrL:13b"]},{"id":"v09-skatteavdragsbrott","title":"Skatteavdragsbrott","shortRef":"SkBrL 6","family":"SkBrL","rule":"taxThreshold","previousMode":"conditional","ownText":"6 § Den som uppsåtligen eller av grov oaktsamhet underlåter att fullgöra skyldighet att göra skatteavdrag på sätt som föreskrivs i skatteförfarandelagen (2011:1244) döms för skatteavdragsbrott till böter eller fängelse i högst ett år. I ringa fall ska inte dömas till ansvar enligt första stycket. Lag (2011:1247).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SkBrL:13","SkBrL:13b"]},{"id":"v09-skatteredovisningsbrott","title":"Skatteredovisningsbrott","shortRef":"SkBrL 7","family":"SkBrL","rule":"taxOther","previousMode":"conditional","ownText":"7 § Den som, i annat fall än som avses i 2 §, uppsåtligen lämnar oriktig uppgift till 1. en myndighet, om uppgiften rör förhållande som har betydelse för skyldigheten för uppgiftslämnaren eller annan att betala skatt, 2. någon som är skyldig att för henne eller honom innehålla skatt eller lämna kontrolluppgift eller motsvarande underrättelse, om uppgiften rör förhållande som har betydelse för skyldighetens fullgörande eller för skyldigheten för uppgiftslämnaren eller annan att betala skatt, döms för skatteredovisningsbrott till böter eller fängelse i högst sex månader. Detsamma gäller den som, i annat fall än som avses i 2 §, uppsåtligen låter bli att lämna en föreskriven uppgift angående sådant förhållande som anges i första stycket 1 eller 2 till någon som avses där. Detta gäller dock endast under förutsättning att uppgiften ska lämnas utan föreläggande eller uppmaning och inte avser egen inkomstdeklaration. I ringa fall ska det inte dömas till ansvar enligt första eller andra stycket. Lag (2026:109).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SkBrL:13","SkBrL:13b"]},{"id":"v09-vardslos-skatteredovisning","title":"Vårdslös skatteredovisning","shortRef":"SkBrL 8","family":"SkBrL","rule":"taxOther","previousMode":"conditional","ownText":"8 § Den som av grov oaktsamhet begår en gärning som avses i 7 § första stycket 2 eller andra stycket döms för vårdslös skatteredovisning till böter eller fängelse i högst sex månader. I ringa fall ska det inte dömas till ansvar enligt första stycket. Lag (2026:109).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SkBrL:13","SkBrL:13b"]},{"id":"v09-forsvarande-av-skattekontroll","title":"Försvårande av skattekontroll","shortRef":"SkBrL 10","family":"SkBrL","rule":"taxOther","previousMode":"conditional","ownText":"10 § Den som uppsåtligen eller av grov oaktsamhet åsidosätter bokföringsskyldighet eller sådan skyldighet att föra och bevara räkenskaper, som föreskrivs för vissa uppgiftsskyldiga och därigenom ger upphov till fara för att myndighets kontrollverksamhet vid beräkning eller uppbörd av skatt eller avgift allvarligt försvåras, döms för försvårande av skattekontroll till böter eller fängelse i högst två år eller, om brottet är grovt, till fängelse i lägst sex månader och högst fyra år. I ringa fall ska det inte dömas till ansvar enligt första stycket. Lag (2026:109).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SkBrL:13","SkBrL:13b"]},{"id":"v09-grovt-forsvarande-av-skattekontroll","title":"Grovt försvårande av skattekontroll","shortRef":"SkBrL 10","family":"SkBrL","rule":"taxOther","previousMode":"conditional","ownText":"10 § Den som uppsåtligen eller av grov oaktsamhet åsidosätter bokföringsskyldighet eller sådan skyldighet att föra och bevara räkenskaper, som föreskrivs för vissa uppgiftsskyldiga och därigenom ger upphov till fara för att myndighets kontrollverksamhet vid beräkning eller uppbörd av skatt eller avgift allvarligt försvåras, döms för försvårande av skattekontroll till böter eller fängelse i högst två år eller, om brottet är grovt, till fängelse i lägst sex månader och högst fyra år. I ringa fall ska det inte dömas till ansvar enligt första stycket. Lag (2026:109).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","SkBrL:13","SkBrL:13b"]},{"id":"v09-bidragsbrott","title":"Bidragsbrott","shortRef":"BidrBrL 2","family":"BidrBrL","rule":"benefit","previousMode":"conditional","ownText":"2 § Den som lämnar oriktiga uppgifter eller inte anmäler ändrade förhållanden som han eller hon är skyldig att anmäla enligt lag eller förordning, och på så sätt orsakar fara för att en ekonomisk förmån eller ett ekonomiskt stöd felaktigt betalas ut, felaktigt tillgodoräknas, betalas ut med ett för högt belopp eller tillgodoräknas med ett för högt belopp, döms för bidragsbrott till fängelse i högst två år eller, om brottet är ringa, till böter eller fängelse i högst sex månader. Lag (2019:652).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","BidrBrL:6","BidrBrL:6a"]},{"id":"v09-ringa-bidragsbrott","title":"Ringa bidragsbrott","shortRef":"BidrBrL 2","family":"BidrBrL","rule":"benefit","previousMode":"conditional","ownText":"2 § Den som lämnar oriktiga uppgifter eller inte anmäler ändrade förhållanden som han eller hon är skyldig att anmäla enligt lag eller förordning, och på så sätt orsakar fara för att en ekonomisk förmån eller ett ekonomiskt stöd felaktigt betalas ut, felaktigt tillgodoräknas, betalas ut med ett för högt belopp eller tillgodoräknas med ett för högt belopp, döms för bidragsbrott till fängelse i högst två år eller, om brottet är ringa, till böter eller fängelse i högst sex månader. Lag (2019:652).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","BidrBrL:6","BidrBrL:6a"]},{"id":"v09-grovt-bidragsbrott","title":"Grovt bidragsbrott","shortRef":"BidrBrL 3","family":"BidrBrL","rule":"benefit","previousMode":"conditional","ownText":"3 § Om brott som avses i 2 § är grovt, döms för grovt bidragsbrott till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. brottet rört betydande belopp, 2. den som begått brottet använt falska handlingar, eller 3. gärningen ingått i en brottslighet som utövats systematiskt eller i större omfattning. Lag (2026:1322).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","BidrBrL:6","BidrBrL:6a"]},{"id":"v09-vardslost-bidragsbrott","title":"Vårdslöst bidragsbrott","shortRef":"BidrBrL 4","family":"BidrBrL","rule":"benefit","previousMode":"conditional","ownText":"4 § Den som av grov oaktsamhet begår en sådan gärning som avses i 2 §, döms för vårdslöst bidragsbrott till böter eller fängelse i högst ett år. Om gärningen med hänsyn till beloppet, risken för slutlig ekonomisk skada och övriga omständigheter är mindre allvarlig, döms inte till ansvar. Lag (2019:652).","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8","BidrBrL:6","BidrBrL:6a"]},{"id":"v09-brott-mot-tillstandsplikten-for-brandfarliga-varor","title":"Brott mot tillståndsplikten för brandfarliga varor","shortRef":"LBE 29","family":"LBE","rule":"LBE","previousMode":"general","ownText":"29 § Den som av oaktsamhet bryter mot 16 § första stycket döms till böter. Den som uppsåtligen eller av grov oaktsamhet bryter mot 16 § första stycket döms till 1. böter eller fängelse i högst ett år om brottet avser brandfarliga varor, eller 2. böter eller fängelse i högst fem år om brottet avser explosiva varor. Lag (2023:874) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"v09-brott-mot-tillstandsplikten-for-explosiva-varor","title":"Brott mot tillståndsplikten för explosiva varor","shortRef":"LBE 29","family":"LBE","rule":"LBE","previousMode":"general","ownText":"29 § Den som av oaktsamhet bryter mot 16 § första stycket döms till böter. Den som uppsåtligen eller av grov oaktsamhet bryter mot 16 § första stycket döms till 1. böter eller fängelse i högst ett år om brottet avser brandfarliga varor, eller 2. böter eller fängelse i högst fem år om brottet avser explosiva varor. Lag (2023:874) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"v09-grovt-brott-mot-tillstandsplikten-for-explosiva-varor","title":"Grovt brott mot tillståndsplikten för explosiva varor","shortRef":"LBE 29 a","family":"LBE","rule":"LBE","previousMode":"general","ownText":"29 a § Om uppsåtligt brott mot 16 § första stycket avser explosiva varor och är att anse som grovt döms till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. varan med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. hanteringen, överföringen, importen eller exporten har avsett flera varor eller en stor mängd av en vara, 3. hanteringen eller överföringen har skett i en sådan miljö att varan typiskt sett kan befaras komma till brottslig användning, eller 4. gärningen annars har varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt döms till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om hanteringen, överföringen, importen eller exporten har avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:874) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]},{"id":"v09-synnerligen-grovt-brott-mot-tillstandsplikten-for-explosiva-varor","title":"Synnerligen grovt brott mot tillståndsplikten för explosiva varor","shortRef":"LBE 29 a","family":"LBE","rule":"LBE","previousMode":"general","ownText":"29 a § Om uppsåtligt brott mot 16 § första stycket avser explosiva varor och är att anse som grovt döms till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. varan med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. hanteringen, överföringen, importen eller exporten har avsett flera varor eller en stor mängd av en vara, 3. hanteringen eller överföringen har skett i en sådan miljö att varan typiskt sett kan befaras komma till brottslig användning, eller 4. gärningen annars har varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt döms till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om hanteringen, överföringen, importen eller exporten har avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:874) .","sourceRefs":["RB:20:2","RB:20:3","RB:20:4","RB:20:5","RB:20:6","BrB:2:2","BrB:2:7","BrB:2:8"]}],rules={"NSL":{"mode":"general","refs":[],"label":"Allmänt åtal enligt huvudregeln","text":"Denna narkotikabrottsrubricering hör enligt RB 20:3 till allmänt åtal. Narkotikastrafflagen har inget särskilt angivelse- eller allmänsynpunktsvillkor för den här katalogposten. Regler om ringa gärning, medverkan, förstadier och förverkande är andra frågor och ska inte presenteras som åtalsvillkor."},"VapenL":{"mode":"conditional","refs":["Vapen:18:14"],"label":"Frivillig inlämning – särskild åtalsprövning","text":"VapenL 18:14 gäller när någon frivilligt lämnar in skjutvapen, ammunition, ljuddämpare eller vapenmagasin till Polismyndigheten. Åtal för personens olovliga innehav får då väckas endast om det är motiverat från allmän synpunkt. Det är ingen automatisk vapenamnesti och gäller inte utan vidare andra gärningsformer, exempelvis tillverkning eller överlåtelse. Utred frivilligheten, den inlämnade egendomen och vilket innehav åtalet skulle avse; brottets grad eller oaktsamhetsform ersätter inte denna kontroll."},"TBL":{"mode":"general","refs":[],"label":"Allmänt åtal enligt huvudregeln","text":"Denna trafikbrottsrubricering hör under allmänt åtal enligt RB 20:3. Trafikbrottslagen uppställer inte ett särskilt krav på målsägandens angivelse för den här posten. Behörighetskrav, alkohol-/narkotikarekvisit, påföljdsfrågor och återkallelse av körkort är separata frågor."},"KnivL":{"mode":"general","refs":[],"label":"Allmänt åtal enligt huvudregeln","text":"Brottet hör enligt RB 20:3 under allmänt åtal. Knivlagen har inget särskilt angivelse- eller allmänsynpunktsvillkor för denna rubricering. Att ett innehav kan vara befogat eller att en ringa gärning inte ska föranleda ansvar gäller straffansvarets förutsättningar, inte vem som får väcka åtal."},"PTBL":{"mode":"general","refs":[],"label":"Allmänt åtal enligt huvudregeln","text":"Denna penningtvättsrubricering hör under allmänt åtal enligt RB 20:3. Penningtvättsbrottslagen uppställer inte något särskilt krav på målsägandens angivelse för posten. Vilken grundgärning, skuldform eller näringsanknytning som krävs är separata materiella frågor; en ringa grad innebär inte i sig enskilt åtal."},"LBE":{"mode":"general","refs":[],"label":"Allmänt åtal enligt huvudregeln","text":"Brottet mot tillståndsplikten hör enligt RB 20:3 under allmänt åtal. LBE har inget särskilt angivelsekrav för denna katalogpost. Reglerna om vite, ringa gärning och subsidiaritet kan påverka straffansvaret och måste prövas separat; de ska inte blandas ihop med en särskild åtalsprövningsregel."},"smuggleFee":{"mode":"conditional","refs":["SmuglL:20"],"label":"Särskilda skäl vid angiven in-/utförselavgift","text":"SmuglL 20 § första stycket 1 gäller de uttryckligen angivna gärningarna enligt 3, 4 eller 7 § (och angivna försök) när de kan föranleda den särskilda in- eller utförselavgiften enligt lagen (1975:85). Då kräver åtal särskilda skäl. Alla tullkostnader eller andra avgifter utlöser inte regeln. Andra stycket omfattar även talan om förverkande i dessa fall."},"smuggleSurcharge":{"mode":"conditional","refs":["SmuglL:20"],"label":"Särskilda skäl vid tulltillägg","text":"SmuglL 20 § första stycket 2 gäller de angivna gärningarna enligt 8, 9 eller 11 § (och angivna försök), om de kan föranleda tulltillägg enligt 5 kap. 5–10 §§ tullagen. Åtal kräver då särskilda skäl. Att en tullskuld finns är inte utan vidare samma sak som att tulltillägg kan påföras. Andra stycket gäller även talan om förverkande i de angivna fallen."},"smuggleGeneral":{"mode":"general","refs":["SmuglL:20"],"label":"Allmänt åtal – inte uppräknad i 20 §","text":"Denna rubricering räknas inte upp i SmuglL 20 § första styckets särskilda åtalsregel. Regeln får inte föras över från en annan smugglingsgrad eller varutyp bara därför att bestämmelserna finns i samma lag. RB 20:3 är utgångspunkten. Frivillig rättelse och andra ansvarsfrihetsregler prövas separat."},"taxMinor":{"mode":"conditional","refs":["SkBrL:13","SkBrL:13b"],"label":"Särskilda skäl och prövning av sanktionsspärr","text":"Skatteförseelse enligt 3 § får enligt 13 § åtalas endast om det är påkallat av särskilda skäl. Detta krav gäller inte först när ett visst belopp underskrids; tvåprisbasbeloppsvillkoren avser de andra uttryckligen nämnda brotten. Därutöver måste spärren i 13 b § prövas. Varken angivelse eller en allmän önskan om lagföring ersätter prövningarna."},"taxThreshold":{"mode":"conditional","refs":["SkBrL:13","SkBrL:13b"],"label":"Belopps-/skattetilläggsvillkor och sanktionsspärr","text":"För brott enligt 2, 5 eller 6 § kräver 13 § särskilda skäl när det undandragna skattebeloppet understiger två prisbasbelopp OCH samma felaktighet eller passivitet även kan ligga till grund för skattetillägg för samma person. Använd prisbasbeloppet för det år då brottet begicks. Beloppsgränsen ensam räcker inte för detta åtalsvillkor. 13 b § är en annan spärr och ska också prövas."},"taxOther":{"mode":"conditional","refs":["SkBrL:13","SkBrL:13b"],"label":"Pröva skattetilläggs-/rapportavgiftsspärr","text":"Denna rubricering räknas inte upp bland brotten i 13 § som omfattas av dess särskilda-skäl-prövning. Tvåprisbasbeloppsregeln får därför inte föras över till den genom enbart gemensam brottsfamilj. 13 b § kan ändå hindra åtal, strafföreläggande eller åtalsunderlåtelse för samma person och samma felaktighet eller passivitet; den måste kontrolleras separat."},"benefit":{"mode":"conditional","refs":["BidrBrL:6","BidrBrL:6a"],"label":"Pröva administrativ sanktionsavgift för samma person","text":"BidrBrL 6 a § hindrar åtal, strafföreläggande och åtalsunderlåtelse när samma uppgiftslämnande eller anmälningsunderlåtenhet redan har legat till grund för beslut om administrativ sanktionsavgift för samma person. Detta är en spärr, inte en fri bedömning som kan ersättas av allmän synpunkt. 6 § reglerar myndigheters anmälningsskyldighet och har ett annat undantag vid möjlig sanktionsavgift: misstänkt grovt bidragsbrott eller särskilda skäl. Skilj den anmälningsfrågan från åklagarens spärr enligt 6 a §."}},pins={"RB:20:2":{"text":"2 § Allmän åklagare äge tala å brott, som hör under allmänt åtal, om ej annat är stadgat. Om befogenhet för särskild åklagare att tala å brott, som hör under allmänt åtal, gälle vad särskilt är föreskrivet. Åklagare må i högre rätt fullfölja talan även till den misstänktes förmån.","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/rattegangsbalk-1942740_sfs-1942-740/"},"RB:20:3":{"text":"3 § Under allmänt åtal höra alla brott, som ej uttryckligen äro undantagna därifrån. Är för allmänt åtal stadgat särskilt villkor, såsom tillstånd av myndighet eller angivelse av målsägande, vare det gällande.","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/rattegangsbalk-1942740_sfs-1942-740/"},"RB:20:4":{"text":"4 § Innefattar en handling flera brott och hör något av dem under allmänt åtal, må sådant åtal äga rum även för de övriga. Har någon angivits för brott, som allenast efter angivelse hör under allmänt åtal, och äro flera misstänkta för att hava tagit del i brottet, må allmänt åtal äga rum mot dem alla.","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/rattegangsbalk-1942740_sfs-1942-740/"},"RB:20:5":{"text":"5 § En målsägande får ange ett brott till åtal hos åklagare eller Polismyndigheten. Lag (2014:649).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/rattegangsbalk-1942740_sfs-1942-740/"},"RB:20:6":{"text":"6 § Åklagare skall, om ej annat är stadgat, tala å brott, som hör under allmänt åtal. Lag (1964:166).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/rattegangsbalk-1942740_sfs-1942-740/"},"BrB:2:2":{"text":"2 § Åtal för brott som avses i 1 § får i följande fall väckas endast om åtalsförordnande har meddelats, nämligen om brottet 1. har begåtts av en utlänning på ett utländskt fartyg eller luftfartyg och riktat sig mot en sådan utlänning eller mot utländskt intresse, 2. har begåtts av en utlänning i utövningen av tjänst eller uppdrag som innefattar allmän ställning hos en annan stat eller en mellanfolklig organisation, om inte gärningsmannen genom vilseledande uppgifter, förklädnad eller på annat sätt har försökt dölja i vilken egenskap han eller hon har handlat, 3. har begåtts av en utlänning som saknar hemvist i Sverige men som befinner sig här i landet inom ramen för internationellt militärt samarbete eller internationell krishantering och som omfattas av avtal som är i kraft i förhållande till Sverige, 4. har begåtts av en svensk medborgare eller utlänning med hemvist i Sverige som tjänstgör i en annan stats militära styrka och som befinner sig här i landet inom ramen för internationellt militärt samarbete eller internationell krishantering och som omfattas av avtal som är i kraft i förhållande till Sverige, 5. är aggressionsbrott enligt 11 a § lagen (2014:406) om straff för vissa internationella brott eller försök, förberedelse eller stämpling till eller underlåtenhet att avslöja eller förhindra sådant brott, eller 6. har riktats mot Internationella brottmålsdomstolens rättskipning. Beslut om åtalsförordnande enligt första stycket 1-5 fattas av regeringen. För beslut om åtalsförordnande enligt första stycket 6 tillämpas 8 §. Lag (2021:1014).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:2:7":{"text":"7 § Åtal för brott som avses i 3 och 4 §§ får väckas endast om åtalsförordnande har meddelats i enlighet med 8 §. Ett sådant åtalsförordnande krävs dock inte om brottet 1. har begåtts ombord på ett svenskt fartyg eller luftfartyg eller i tjänsten av befälhavaren eller någon som tillhörde besättningen på ett sådant fartyg, 2. har begåtts i utövningen av tjänst eller uppdrag som innefattar svensk allmän ställning, 3. har begåtts av någon som tillhör Försvarsmakten på ett område där en avdelning av Försvarsmakten befann sig, 4. har begåtts vid tjänstgöringen av någon som är anställd av en svensk myndighet för att delta i en internationell militär insats eller i internationell civil krishantering, 5. har begåtts i Danmark, Finland, Island eller Norge eller på fartyg eller luftfartyg i reguljär trafik mellan orter belägna i Sverige eller någon av dessa stater, 6. har begåtts mot svenskt intresse av en svensk, dansk, finsk, isländsk eller norsk medborgare eller av en utlänning med hemvist i Sverige, eller 7. är osann utsaga eller ovarsam utsaga inför en internationell domstol. Andra stycket gäller dock inte i fråga om brott som riktats mot Internationella brottmålsdomstolens rättskipning. Lag (2021:1014).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:2:8":{"text":"8 § Riksåklagaren beslutar om åtalsförordnande om inte annat är särskilt föreskrivet. Vid denna prövning ska det särskilt beaktas 1. om ett åtal här i landet är förenligt med Sveriges folkrättsliga förpliktelser, 2. i vilken utsträckning brottsligheten eller den misstänkte har anknytning till Sverige, 3. om åtgärder för lagföring har inletts eller kommer att inledas i en annan stat eller vid en internationell domstol, och 4. vilka faktiska möjligheter det finns att utreda brottet och lagföra den misstänkte här. När det gäller brott som har begåtts utomlands av någon som vid gärningstillfället var svensk medborgare eller hade hemvist i Sverige eller, när åtal väcks för brottet, är svensk medborgare eller har hemvist i Sverige, får riksåklagaren överlämna prövningen till en annan allmän åklagare. Om det finns anledning att anta att prövningen har särskild betydelse för Sveriges utrikes- eller säkerhetspolitik och riksåklagaren bedömer att det inte finns hinder mot att väcka åtal, ska riksåklagaren med eget yttrande överlämna ärendet till regeringen för beslut. Lag (2021:1014).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"Vapen:18:14":{"text":"14 § Om någon frivilligt lämnar in skjutvapen, ammunition, ljuddämpare eller vapenmagasin till Polismyndigheten, får åtal för olovligt innehav av egendomen väckas mot honom eller henne av åklagaren endast om det är motiverat från allmän synpunkt.","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/vapenlag-2026408_sfs-2026-408/"},"SmuglL:20":{"text":"20 § Kan brott som avses i 1. 3 eller 4 § eller försök till sådant brott eller 7 § föranleda att en sådan avgift som avses i 3 § lagen (1975:85) med bemyndigande att meddela föreskrifter om in- eller utförsel av varor påförs, eller 2. 8 eller 9 § eller försök till sådant brott eller 11 § föranleda att tulltillägg enligt 5 kap. 5-10 §§ tullagen (2016:253) påförs får åtal för brottet väckas endast om det är påkallat av särskilda skäl. Vad som sägs i första stycket gäller även talan om förverkande på grund av brott enligt denna lag. Lag (2024:842).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/lag-20001225-om-straff-for-smuggling_sfs-2000-1225/"},"SkBrL:13":{"text":"13 § Åtal för brott enligt 3 § får väckas endast om det är påkallat av särskilda skäl. Detsamma gäller åtal för brott enligt 2, 5 och 6 §§, om 1. det undandragna skattebeloppet understiger två prisbasbelopp, och 2. en felaktighet eller passivitet som skulle omfattas av åtalet även kan läggas till grund för beslut om skattetillägg för samma person. Med prisbasbelopp avses det prisbasbelopp enligt 2 kap. 6 och 7 §§ socialförsäkringsbalken som gällde det år då brottet begicks. Lag (2015:634).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/skattebrottslag-197169_sfs-1971-69/"},"SkBrL:13b":{"text":"13 b § Om Skatteverket har beslutat att ta ut skattetillägg av en fysisk person, får åklagaren inte väcka åtal, utfärda strafföreläggande eller besluta om åtalsunderlåtelse för samma person i fråga om den felaktighet eller passivitet som ligger till grund för beslutet om skattetillägg. Om Skatteverket har krävt en fysisk person på betalning av ett skattetillägg eller en rapportavgift som avser en juridisk person eller om en överenskommelse om betalningsskyldighet enligt 59 kap. 19 § skatteförfarandelagen (2011:1244) har träffats och fullföljts inom rätt tid, får åklagaren inte väcka åtal, utfärda strafföreläggande eller besluta om åtalsunderlåtelse för samma fysiska person i fråga om den felaktighet eller passivitet som ligger till grund för beslutet om skattetillägg eller rapportavgift. Lag (2023:876).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/skattebrottslag-197169_sfs-1971-69/"},"BidrBrL:6":{"text":"6 § Myndigheter som anges i 1 § samt kommuner och arbetslöshetskassor ska göra anmälan till Polismyndigheten om det kan misstänkas att brott enligt denna lag har begåtts. Om en administrativ sanktionsavgift kan påföras samma person för samma gärning som misstanken avser gäller anmälningsskyldigheten i första stycket endast om det kan misstänkas att brott enligt 3 § har begåtts eller om det finns särskilda skäl. Lag (2026:725).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/bidragsbrottslag-2007612_sfs-2007-612/"},"BidrBrL:6a":{"text":"6 a § Åklagaren får inte väcka åtal, utfärda strafföreläggande eller besluta om åtalsunderlåtelse i fråga om ett oriktigt uppgiftslämnande eller en underlåtenhet att anmäla ändrade förhållanden, om uppgiftslämnandet eller underlåtenheten har legat till grund för ett beslut om administrativ sanktionsavgift för samma person som åklagarens åtgärd skulle avse. Lag (2026:725).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/bidragsbrottslag-2007612_sfs-2007-612/"}},urls={"NSL":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/narkotikastrafflag-196864_sfs-1968-64/","VapenL":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/vapenlag-2026408_sfs-2026-408/","TBL":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/lag-1951649-om-straff-for-vissa-trafikbrott_sfs-1951-649/","KnivL":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/lag-1988254-om-forbud-betraffande-knivar-och_sfs-1988-254/","SmuglL":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/lag-20001225-om-straff-for-smuggling_sfs-2000-1225/","PTBL":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/lag-2014307-om-straff-for-penningtvattsbrott_sfs-2014-307/","SkBrL":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/skattebrottslag-197169_sfs-1971-69/","BidrBrL":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/bidragsbrottslag-2007612_sfs-2007-612/","LBE":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/lag-20101011-om-brandfarliga-och-explosiva_sfs-2010-1011/"},versions={"SmuglL":"2026:1321","PTBL":"2026:1323","SkBrL":"2026:1531","BidrBrL":"2026:1322","LBE":"2026:1584"};
const norm=s=>String(s||'').replace(/\s+/g,' ').trim();
const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Stockholm'});
const validDate=s=>/^\d{4}-\d{2}-\d{2}$/.test(s||'')&&!Number.isNaN(Date.parse(s))&&s<=today;
const ready=k=>{const p=W[k];return p?.complete===true&&p.completeTextProvenance==='manual-crosscheck-current-SFS-paragraph-only'&&validDate(p.checked)&&p.url===pins[k]?.url&&norm(p.text)===pins[k]?.text;};
const sourceReady=Object.fromEntries(Object.keys(pins).map(k=>[k,ready(k)]));
const rb=pins['RB:20:3'].url;
const report={planned:68,completed:0,byFamily:{},held:[],correctedModes:[],checked:'2026-10-20',fullLegalApprovals:0,caseSpecificChargingApprovals:0,coercionApprovals:0};
const map=new Map(D.crimes.map(c=>[c.id,c]));
for(const row of rows){const c=map.get(row.id),rule=rules[row.rule],sourceURL=urls[row.family];
 const versionOK=!versions[row.family]||window.BK_SPECIAL_EXCERPTS?.[row.family]?.observedVersion===versions[row.family];
 if(!c||c.stageType||c.title!==row.title||c.shortRef!==row.shortRef||c.prosecution!==row.previousMode
  ||c.lawMode!=='full'||c.lawCompletenessVerified!==true||c.lawCompletenessSourceURL!==sourceURL||!validDate(c.lawCompletenessChecked)
  ||norm(c.law)!==row.ownText||!row.sourceRefs.every(k=>sourceReady[k])||!versionOK||c.legalAudit15?.checkpoints?.prosecution){report.held.push(row.title);continue;}
 const notes=['BrB 2:2 innehåller särskilda fall av åtalsförordnande även för gärningar i Sverige. För utlandsbrott prövas 2:7 och dess undantag; 2:8 anger riksåklagaren som utgångspunkt för beslut och reglerar andra beslutsordningar. Den här kontrollen avgör inte jurisdiktion, immunitet, gärningsdag, preskription eller faktisk beslutskompetens i ärendet.'];
 if(row.family==='SkBrL')notes.push('13 b § första stycket gäller beslutat skattetillägg för en fysisk person och samma felaktighet/passivitet. Andra stycket omfattar också de angivna fallen där en fysisk person krävts på betalning av en juridisk persons skattetillägg eller rapportavgift, eller där en angiven betalningsöverenskommelse har träffats och fullföljts i rätt tid. Personidentitet, beslut och saklig överlappning måste kontrolleras; ett allmänt påstående att skatt redan har betalats avgör inte spärren.');
 if(row.family==='BidrBrL')notes.push('Frivillig rättelse före utbetalning eller tillgodoräknande enligt 5 § gäller materiell ansvarsfrihet. Det är inte samma regel som den administrativa sanktionsspärren i 6 a § eller en myndighets skyldighet att polisanmäla enligt 6 §.');
 if(row.family==='VapenL')notes.push('Frivillig inlämning ska inte automatiskt likställas med beslag efter ett polisiärt ingripande. 18:14 ger ingen automatisk ansvarsfrihet eller rätt att behålla egendomen. Andra brott och gärningsformer bedöms för sig.');
 const finding=row.title+' ('+row.shortRef+'): '+rule.text;
 c.prosecutionStatutoryReview15={checked:report.checked,rule:row.rule,classification:rule.mode,label:rule.label,sourceURL,sourceLabel:row.family+' – aktuella åtalsregler',supportingSourceURL:rb,sourceRefs:[row.shortRef,...row.sourceRefs],finding,notes,interpretation:null,scope:'current-statutory-offence-specific-prosecution-filters-only',caseSpecificProsecutionApproved:false,fullLegalReviewApproved:false};
 c.legalAudit15={...c.legalAudit15,fullLegalReviewApproved:false,checkpoints:{...c.legalAudit15?.checkpoints,prosecution:{status:'APPROVED',checked:report.checked,sourceURL,sourceRefs:[row.shortRef,...row.sourceRefs],supportingSourceURLs:[rb],scope:'current-statutory-offence-specific-prosecution-filters-only',finding,caseSpecificLiabilityApproved:false,caseSpecificCustodyApproved:false,caseSpecificChargingApproved:false,historicLawApproved:false,jurisprudenceApproved:false,jurisdictionAndImmunityInConcreteCaseApproved:false}}};
 if(c.prosecution!==rule.mode){c.prosecution=rule.mode;c.prosecutionLabel=rule.label;c.prosecutionRule='VapenL 18:14; RB 20:3';c.prosecutionDetails=[rule.text,...notes];c.prosecutionSource=c.prosecutionRule;c.prosecutionSourceURL=sourceURL;c.prosecutionChecked=report.checked;c.prosecutionReviewStatus='individual-current-special-prosecution-audit-2026-10-20';report.correctedModes.push(row.title);}
 report.completed++;report.byFamily[row.family]=(report.byFamily[row.family]||0)+1;
}
window.BK_SPECIAL_PROSECUTION_AUDIT15=report;
})();
